-- Aether Flow / Aether Works
-- Conhecimento comercial derivado do PDF AETHER_AI_CONHECIMENTO_7_LIVROS_2026-09-28.pdf
-- Gerado a partir da extração completa das 21 páginas do PDF em 2026-10-06.
-- Este arquivo cria um acervo consultável; ele não aplica a migration nem altera produção.
-- O próprio PDF registra limitações de OCR, páginas sem texto e que é uma síntese dos livros.

begin;

create table if not exists public.aether_negotiation_documents (
  document_key text primary key,
  title text not null,
  source_url text not null,
  source_drive_file_id text not null,
  version text,
  published_on date,
  page_count integer not null,
  provenance text not null,
  limitations text not null,
  created_at timestamptz not null default now()
);

create table if not exists public.aether_negotiation_catalog (
  document_key text primary key references public.aether_negotiation_documents(document_key) on delete cascade,
  spreadsheet_id text not null,
  spreadsheet_title text not null,
  sheet_name text not null,
  spreadsheet_updated_at timestamptz,
  resource_title text not null,
  resource_date date,
  scope text not null,
  usage_in_jarvis text not null,
  access_url text not null,
  catalog_provenance text not null
);

create table if not exists public.aether_negotiation_pages (
  document_key text not null references public.aether_negotiation_documents(document_key) on delete cascade,
  page_number integer not null check (page_number > 0),
  body text not null,
  primary key (document_key, page_number)
);

create table if not exists public.aether_negotiation_sources (
  document_key text not null references public.aether_negotiation_documents(document_key) on delete cascade,
  source_key text not null,
  title text not null,
  author text not null,
  extracted_pages text not null,
  limitation text not null,
  primary key (document_key, source_key)
);

create table if not exists public.aether_negotiation_rules (
  document_key text not null references public.aether_negotiation_documents(document_key) on delete cascade,
  rule_key text not null,
  category text not null,
  stage text not null,
  priority integer not null,
  rule_text text not null,
  operational_detail text not null,
  source_basis text not null,
  primary key (document_key, rule_key)
);

create table if not exists public.aether_negotiation_scenarios (
  document_key text not null references public.aether_negotiation_documents(document_key) on delete cascade,
  scenario_key text not null,
  signal text not null,
  recommended_action text not null,
  avoid_action text not null,
  primary key (document_key, scenario_key)
);

