insert into public.aether_negotiation_rules (document_key, rule_key, category, stage, priority, rule_text, operational_detail, source_basis) values ('aether_ai_7_books_2026_09_28', E'priority_truth_consent', E'priority', E'all', 1, E'Verdade, consentimento e limites éticos vêm antes de qualquer técnica de influência.', E'Não inventar provas, resultados, clientes, urgência, escassez ou autoridade; não esconder custo ou condição material; não explorar vulnerabilidade.', E'SÍNTESE; regras 3 e 21') on conflict (document_key, rule_key) do update set category=excluded.category, stage=excluded.stage, priority=excluded.priority, rule_text=excluded.rule_text, operational_detail=excluded.operational_detail, source_basis=excluded.source_basis;
