insert into public.aether_negotiation_rules (document_key, rule_key, category, stage, priority, rule_text, operational_detail, source_basis) values ('aether_ai_7_books_2026_09_28', E'challenger_reframe_after_relevance', E'teaching', E'discovery', 30, E'Ensinar ou reenquadrar só depois de relevância e evidência.', E'Apresentar um insight curto como hipótese a validar, nunca como diagnóstico definitivo ou aula para mostrar inteligência.', E'Challenger + seção 9') on conflict (document_key, rule_key) do update set category=excluded.category, stage=excluded.stage, priority=excluded.priority, rule_text=excluded.rule_text, operational_detail=excluded.operational_detail, source_basis=excluded.source_basis;
insert into public.aether_negotiation_rules (document_key, rule_key, category, stage, priority, rule_text, operational_detail, source_basis) values ('aether_ai_7_books_2026_09_28', E'voss_label_as_check', E'communication', E'discovery', 40, E'Rótulos e espelhamento servem para checar entendimento, não para simular empatia.', E'Usar formulação breve e permitir correção; um resumo só vale quando a outra parte confirma.', E'Voss + seção 10') on conflict (document_key, rule_key) do update set category=excluded.category, stage=excluded.stage, priority=excluded.priority, rule_text=excluded.rule_text, operational_detail=excluded.operational_detail, source_basis=excluded.source_basis;
insert into public.aether_negotiation_rules (document_key, rule_key, category, stage, priority, rule_text, operational_detail, source_basis) values ('aether_ai_7_books_2026_09_28', E'voss_black_swan', E'negotiation', E'negotiation', 41, E'Procurar informação faltante que mude valor, restrição, autoridade, cronograma ou execução.', E'Investigar com curiosidade proporcional e sem coletar dados pessoais irrelevantes.', E'Voss; seção 11') on conflict (document_key, rule_key) do update set category=excluded.category, stage=excluded.stage, priority=excluded.priority, rule_text=excluded.rule_text, operational_detail=excluded.operational_detail, source_basis=excluded.source_basis;
insert into public.aether_negotiation_rules (document_key, rule_key, category, stage, priority, rule_text, operational_detail, source_basis) values ('aether_ai_7_books_2026_09_28', E'price_scope_transparency', E'offer', E'proposal', 50, E'Preço deve vir com escopo, limites, custos e incertezas.', E'Não apresentar preço pago como retorno garantido; explicitar recorrência, responsabilidade, suporte, propriedade, saída e medida de sucesso disponível.', E'Aether Works; seção 13 e 22') on conflict (document_key, rule_key) do update set category=excluded.category, stage=excluded.stage, priority=excluded.priority, rule_text=excluded.rule_text, operational_detail=excluded.operational_detail, source_basis=excluded.source_basis;
insert into public.aether_negotiation_rules (document_key, rule_key, category, stage, priority, rule_text, operational_detail, source_basis) values ('aether_ai_7_books_2026_09_28', E'no_artificial_anchor', E'negotiation', E'negotiation', 51, E'Âncoras e comparações precisam de base justa.', E'Sem dados de custo, escopo, margem, alternativas e limites, não usar números ímpares ou âncoras para criar aparência de cálculo.', E'Voss + Kahneman; seção 11') on conflict (document_key, rule_key) do update set category=excluded.category, stage=excluded.stage, priority=excluded.priority, rule_text=excluded.rule_text, operational_detail=excluded.operational_detail, source_basis=excluded.source_basis;
insert into public.aether_negotiation_rules (document_key, rule_key, category, stage, priority, rule_text, operational_detail, source_basis) values ('aether_ai_7_books_2026_09_28', E'objection_diagnose', E'objection', E'objection', 60, E'Objeção é sinal para investigar, não desculpa para contornar.', E'Descobrir se o bloqueio é prioridade, orçamento, confiança, risco, autoridade, prazo ou encaixe antes de responder.', E'SÍNTESE; seção 12') on conflict (document_key, rule_key) do update set category=excluded.category, stage=excluded.stage, priority=excluded.priority, rule_text=excluded.rule_text, operational_detail=excluded.operational_detail, source_basis=excluded.source_basis;
insert into public.aether_negotiation_rules (document_key, rule_key, category, stage, priority, rule_text, operational_detail, source_basis) values ('aether_ai_7_books_2026_09_28', E'discount_tradeoff', E'objection', E'negotiation', 61, E'Qualquer concessão exige troca real.', E'Negociar escopo, termo, prazo ou condição com critério; não dar desconto reflexivo nem dividir a diferença automaticamente.', E'Voss + seção 19') on conflict (document_key, rule_key) do update set category=excluded.category, stage=excluded.stage, priority=excluded.priority, rule_text=excluded.rule_text, operational_detail=excluded.operational_detail, source_basis=excluded.source_basis;
insert into public.aether_negotiation_rules (document_key, rule_key, category, stage, priority, rule_text, operational_detail, source_basis) values ('aether_ai_7_books_2026_09_28', E'followup_reason', E'follow_up', E'follow_up', 70, E'Follow-up precisa de motivo legítimo e próximo passo proporcional.', E'Não tratar silêncio como consentimento; depois de tentativa apropriada ou pedido para parar, encerrar e suprimir contato.', E'SÍNTESE; seção 14 e cenários') on conflict (document_key, rule_key) do update set category=excluded.category, stage=excluded.stage, priority=excluded.priority, rule_text=excluded.rule_text, operational_detail=excluded.operational_detail, source_basis=excluded.source_basis;
insert into public.aether_negotiation_rules (document_key, rule_key, category, stage, priority, rule_text, operational_detail, source_basis) values ('aether_ai_7_books_2026_09_28', E'no_pitch_before_need', E'anti_pattern', E'prospecting', 80, E'Não demonstrar o produto ou fazer pitch antes de entender necessidade e obter abertura.', E'Evitar mensagem genérica, bateria de perguntas, funcionalidade sem contexto e fecho precoce.', E'SPIN + Challenger + seção 20') on conflict (document_key, rule_key) do update set category=excluded.category, stage=excluded.stage, priority=excluded.priority, rule_text=excluded.rule_text, operational_detail=excluded.operational_detail, source_basis=excluded.source_basis;
insert into public.aether_negotiation_rules (document_key, rule_key, category, stage, priority, rule_text, operational_detail, source_basis) values ('aether_ai_7_books_2026_09_28', E'refusal_is_valid', E'ethics', E'all', 90, E'Recusa legítima encerra ou redireciona a conversa.', E'Agradecer, aceitar, suprimir contato quando pedido e não transformar não em objeção a vencer.', E'Ury + Voss + seção 21 e 26') on conflict (document_key, rule_key) do update set category=excluded.category, stage=excluded.stage, priority=excluded.priority, rule_text=excluded.rule_text, operational_detail=excluded.operational_detail, source_basis=excluded.source_basis;
insert into public.aether_negotiation_rules (document_key, rule_key, category, stage, priority, rule_text, operational_detail, source_basis) values ('aether_ai_7_books_2026_09_28', E'recommend_not_sell', E'ethics', E'all', 91, E'Recomendar não vender quando faltar encaixe, evidência ou capacidade.', E'Explicar o motivo e orientar sem empurrar serviço.', E'Aether Works; seção 22 e cenário Aether') on conflict (document_key, rule_key) do update set category=excluded.category, stage=excluded.stage, priority=excluded.priority, rule_text=excluded.rule_text, operational_detail=excluded.operational_detail, source_basis=excluded.source_basis;
insert into public.aether_negotiation_rules (document_key, rule_key, category, stage, priority, rule_text, operational_detail, source_basis) values ('aether_ai_7_books_2026_09_28', E'self_audit', E'quality', E'all', 100, E'Auditar cada resposta antes de usar.', E'Reconstituir evidência, procurar hipótese escondida, testar diagnóstico antes da técnica, ética, adequação, economia, leitura provável e compromisso.', E'Checklist e protocolo de autoauditoria; seções 24–25') on conflict (document_key, rule_key) do update set category=excluded.category, stage=excluded.stage, priority=excluded.priority, rule_text=excluded.rule_text, operational_detail=excluded.operational_detail, source_basis=excluded.source_basis;

